import fs from 'node:fs'
import path from 'node:path'

export type MacNativeArchitecture = 'arm64' | 'x86_64'

export interface MacNativeCatalogComponentV1 {
  pluginId: string
  dllId: string
  relativePath: string
  identifier: string
  sha256: string
}

/** Values are generated by an approved Darwin build and sealed in the signed app bundle. */
export interface MacNativeRuntimePolicyV1 {
  schemaVersion: 1
  appBundleId: string
  teamId: string
  hostBundleId: string
  workerBundleId: string
  minimumOs: string
  architectures: readonly MacNativeArchitecture[]
  components: readonly MacNativeCatalogComponentV1[]
}

export type MacNativeRuntimeBlockReason =
  | 'runtime-policy-missing'
  | 'runtime-policy-invalid'
  | 'runtime-policy-not-packaged'
  | 'process-architecture-unapproved'
  | 'same-object-load-unproven'

export interface MacNativeRuntimeReadiness {
  available: boolean
  reasons: readonly MacNativeRuntimeBlockReason[]
  policy?: MacNativeRuntimePolicyV1
}

export interface MacNativeComponentCandidate extends MacNativeCatalogComponentV1 {
  absolutePath: string
  teamId: string
  architecture: MacNativeArchitecture
  minimumOs: string
}

export type MacNativeComponentLocation = MacNativeComponentCandidate

const POLICY_FILE_NAME = 'ztools-mac-native-policy.json'
const MAX_POLICY_BYTES = 1024 * 1024
const POLICY_KEYS = new Set([
  'schemaVersion',
  'appBundleId',
  'teamId',
  'hostBundleId',
  'workerBundleId',
  'minimumOs',
  'architectures',
  'components'
])
const COMPONENT_KEYS = new Set(['pluginId', 'dllId', 'relativePath', 'identifier', 'sha256'])
const COMPONENT_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function isBundleIdentifier(value: unknown): value is string {
  return typeof value === 'string' && value.length <= 255 &&
    /^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$/.test(value)
}

function isRelativeDylibPath(value: unknown): value is string {
  if (typeof value !== 'string' || value.length === 0 || value.length > 1024 ||
      value.startsWith('/') || value.includes('\\') || value.includes('\0')) return false
  const segments = value.split('/')
  return segments.length >= 2 && segments[0] === 'lib' &&
    segments.every((segment) => segment.length > 0 && segment !== '.' && segment !== '..' &&
      /^[A-Za-z0-9_.-]+$/.test(segment)) &&
    segments.at(-1)!.toLowerCase().endsWith('.dylib')
}

function parseComponent(value: unknown): MacNativeCatalogComponentV1 | undefined {
  if (!isRecord(value) || Object.keys(value).some((key) => !COMPONENT_KEYS.has(key)) ||
      Object.keys(value).length !== COMPONENT_KEYS.size ||
      typeof value.pluginId !== 'string' || !COMPONENT_ID_PATTERN.test(value.pluginId) ||
      typeof value.dllId !== 'string' || !COMPONENT_ID_PATTERN.test(value.dllId) ||
      !isRelativeDylibPath(value.relativePath) || !isBundleIdentifier(value.identifier) ||
      typeof value.sha256 !== 'string' || !/^[A-Fa-f0-9]{64}$/.test(value.sha256)) {
    return undefined
  }

  return Object.freeze({
    pluginId: value.pluginId,
    dllId: value.dllId,
    relativePath: value.relativePath,
    identifier: value.identifier,
    sha256: value.sha256.toLowerCase()
  })
}

function isMinimumOs(value: unknown): value is string {
  return typeof value === 'string' &&
    /^(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)(?:\.(?:0|[1-9]\d*))?$/.test(value)
}

export function parseMacNativeRuntimePolicy(value: unknown): MacNativeRuntimePolicyV1 | undefined {
  if (!isRecord(value) || Object.keys(value).some((key) => !POLICY_KEYS.has(key)) ||
      Object.keys(value).length !== POLICY_KEYS.size || value.schemaVersion !== 1 ||
      !isBundleIdentifier(value.appBundleId) || !isBundleIdentifier(value.hostBundleId) ||
      !isBundleIdentifier(value.workerBundleId) ||
      typeof value.teamId !== 'string' || !/^[A-Z0-9]{10}$/.test(value.teamId) ||
      !isMinimumOs(value.minimumOs) || !Array.isArray(value.architectures) ||
      value.architectures.length === 0 || value.architectures.length > 2 ||
      !Array.isArray(value.components) || value.components.length === 0 || value.components.length > 512) {
    return undefined
  }

  const architectures: MacNativeArchitecture[] = []
  for (const architecture of value.architectures) {
    if ((architecture !== 'arm64' && architecture !== 'x86_64') || architectures.includes(architecture)) {
      return undefined
    }
    architectures.push(architecture)
  }

  const components: MacNativeCatalogComponentV1[] = []
  const componentKeys = new Set<string>()
  for (const candidate of value.components) {
    const component = parseComponent(candidate)
    if (!component) return undefined
    const key = JSON.stringify([component.pluginId, component.dllId])
    if (componentKeys.has(key)) return undefined
    componentKeys.add(key)
    components.push(component)
  }

  return Object.freeze({
    schemaVersion: 1,
    appBundleId: value.appBundleId,
    teamId: value.teamId,
    hostBundleId: value.hostBundleId,
    workerBundleId: value.workerBundleId,
    minimumOs: value.minimumOs,
    architectures: Object.freeze(architectures),
    components: Object.freeze(components)
  })
}

function mapProcessArchitecture(processArchitecture: string): MacNativeArchitecture | undefined {
  switch (processArchitecture) {
    case 'arm64': return 'arm64'
    case 'x64': return 'x86_64'
    default: return undefined
  }
}

export function resolveMacNativeRuntimeReadiness(
  embeddedPolicy: unknown,
  processArchitecture: string,
  isPackaged = true
): MacNativeRuntimeReadiness {
  if (!isPackaged) return { available: false, reasons: ['runtime-policy-not-packaged'] }
  if (embeddedPolicy === undefined || embeddedPolicy === null) {
    return { available: false, reasons: ['runtime-policy-missing'] }
  }

  const policy = parseMacNativeRuntimePolicy(embeddedPolicy)
  if (!policy) return { available: false, reasons: ['runtime-policy-invalid'] }

  const architecture = mapProcessArchitecture(processArchitecture)
  if (!architecture || !policy.architectures.includes(architecture)) {
    return {
      available: false,
      reasons: ['process-architecture-unapproved'],
      policy
    }
  }

  // The current Darwin loader can only verify the mapped object after dlopen
  // returns, when component initializers may already have executed. Keep the
  // production runtime unavailable until a pre-initializer proof is supported.
  return { available: false, reasons: ['same-object-load-unproven'], policy }
}

/** Reads only the signed app Resources catalog; no setting, Renderer, or runtime API can override it. */
export function readMacNativeRuntimePolicy(
  resourcesPath: string,
  options: { platform?: NodeJS.Platform; isPackaged: boolean } = { isPackaged: false }
): MacNativeRuntimePolicyV1 | undefined {
  if ((options.platform ?? process.platform) !== 'darwin' || !options.isPackaged ||
      typeof resourcesPath !== 'string' || !path.isAbsolute(resourcesPath)) return undefined

  try {
    const resourcesStat = fs.lstatSync(resourcesPath)
    if (!resourcesStat.isDirectory() || resourcesStat.isSymbolicLink()) return undefined
    const policyPath = path.join(resourcesPath, 'native', POLICY_FILE_NAME)
    const nativeStat = fs.lstatSync(path.dirname(policyPath))
    const policyStat = fs.lstatSync(policyPath)
    if (!nativeStat.isDirectory() || nativeStat.isSymbolicLink() || !policyStat.isFile() ||
        policyStat.isSymbolicLink() || policyStat.size <= 0 || policyStat.size > MAX_POLICY_BYTES) {
      return undefined
    }
    const policyRealPath = fs.realpathSync(policyPath)
    if (path.dirname(policyRealPath) !== fs.realpathSync(path.dirname(policyPath))) return undefined
    return parseMacNativeRuntimePolicy(JSON.parse(fs.readFileSync(policyPath, 'utf8')) as unknown)
  } catch {
    return undefined
  }
}

/** Resolves a catalog entry under the fixed plugin root and rejects symlinked path segments. */
export function resolveMacNativeComponentCandidate(
  policy: MacNativeRuntimePolicyV1,
  pluginRoot: string,
  pluginId: string,
  dllId: string,
  processArchitecture: string
): MacNativeComponentCandidate | undefined {
  const location = resolveMacNativeComponentLocation(policy, pluginRoot, pluginId, dllId, processArchitecture)
  if (!location) return undefined

  const pluginDirectory = path.join(pluginRoot, pluginId)
  const candidatePath = location.absolutePath
  try {
    const directories = [pluginRoot, pluginDirectory]
    let current = pluginDirectory
    for (const segment of location.relativePath.split('/').slice(0, -1)) {
      current = path.join(current, segment)
      directories.push(current)
    }
    for (const directory of directories) {
      const stat = fs.lstatSync(directory)
      if (!stat.isDirectory() || stat.isSymbolicLink()) return undefined
    }
    const fileStat = fs.lstatSync(candidatePath)
    if (!fileStat.isFile() || fileStat.isSymbolicLink()) return undefined
    const canonicalPlugin = fs.realpathSync(pluginDirectory)
    const canonicalCandidate = fs.realpathSync(candidatePath)
    const canonicalRelative = path.relative(canonicalPlugin, canonicalCandidate)
    if (canonicalRelative === '..' || canonicalRelative.startsWith(`..${path.sep}`) ||
        path.isAbsolute(canonicalRelative)) return undefined
  } catch {
    return undefined
  }

  return location
}

/** Pure Main-side catalog lookup; the Host repeats filesystem and trust checks. */
export function resolveMacNativeComponentLocation(
  policy: MacNativeRuntimePolicyV1,
  pluginRoot: string,
  pluginId: string,
  dllId: string,
  processArchitecture: string
): MacNativeComponentLocation | undefined {
  const architecture = mapProcessArchitecture(processArchitecture)
  if (!architecture || !policy.architectures.includes(architecture) ||
      typeof pluginRoot !== 'string' || !path.isAbsolute(pluginRoot) ||
      typeof pluginId !== 'string' || typeof dllId !== 'string') return undefined

  const component = policy.components.find((item) => item.pluginId === pluginId && item.dllId === dllId)
  if (!component) return undefined

  const pluginDirectory = path.join(pluginRoot, pluginId)
  const candidatePath = path.resolve(pluginDirectory, ...component.relativePath.split('/'))
  const relativeToPlugin = path.relative(path.resolve(pluginDirectory), candidatePath)
  if (relativeToPlugin === '..' || relativeToPlugin.startsWith(`..${path.sep}`) || path.isAbsolute(relativeToPlugin)) {
    return undefined
  }

  return Object.freeze({
    ...component,
    absolutePath: candidatePath,
    teamId: policy.teamId,
    architecture,
    minimumOs: policy.minimumOs
  })
}
